population_stability<-function(reference,current,binning,metrics,smoothing,design,reference_weights=NULL,current_weights=NULL,context=NULL){
 d<-.vb_design(design,context,FALSE);spec<-.ex_object(binning,'binning');metric_names<-.ex_ids(metrics,'metrics');alpha<-.vb_number(smoothing,'smoothing',0);if(length(setdiff(metric_names,c('psi','jsd','wasserstein')))) .cr_error('VALIDATION_DRIFT','Unknown metric');for(k in c('binning_id','version')).vb_string(spec[[k]],k);known<-.cr_data_date(spec$known_at,'binning known_at');reference_asof<-.cr_data_date(d$reference_as_of,'reference_as_of');current_asof<-.cr_data_date(d$current_as_of,'current_as_of');if(known>min(reference_asof,current_asof)||max(reference_asof,current_asof)>.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff')) .cr_error('VALIDATION_LOOKAHEAD','Bins must precede samples, samples precede evaluation');reference<-as.list(reference);current<-as.list(current);missing<-function(v)is.null(v)||(length(v)==1L&&is.na(v));kind<-spec$kind
 if(kind=='numeric'){cuts<-.vb_vec(spec$cutpoints,'cutpoints',empty=TRUE);support<-.vb_vec(spec$reference_support,'reference_support');if(any(diff(cuts)<=0)||length(support)!=2L||support[1]>=support[2]) .cr_error('VALIDATION_BINS','Increasing cutpoints and ordered support required');size<-length(cuts)+2L;encode<-function(v)if(missing(v))size else sum(cuts<.vb_number(v,'value'))+1L;novel<-function(v)!missing(v)&&!(.vb_number(v,'value')>=support[1]&&.vb_number(v,'value')<=support[2])
 }else if(kind=='categorical'){levels<-.ex_ids(spec$levels,'levels');size<-length(levels)+2L;encode<-function(v){if(missing(v))return(size-1L);.vb_string(v,'categorical value');index<-match(v,levels);if(is.na(index))size else index};novel<-function(v)!missing(v)&&!(v%in%levels);if('wasserstein'%in%metric_names) .cr_error('VALIDATION_DRIFT','Wasserstein requires numeric distances')
 }else .cr_error('VALIDATION_BINS','Numeric or categorical bins required')
 sample<-function(values,weights){w<-if(is.null(weights))rep(1,length(values))else .vb_vec(weights,'weights',empty=TRUE);if(length(w)!=length(values)||any(w<0)||!is.finite(sum(w))) .cr_error('VALIDATION_WEIGHT','Aligned nonnegative finite-sum weights required');counts<-numeric(size);for(i in seq_along(values)){j<-encode(values[[i]]);counts[j]<-counts[j]+w[i]};list(weights=w,counts=counts)};a_sample<-sample(reference,reference_weights);b_sample<-sample(current,current_weights);wr<-a_sample$weights;wc<-b_sample$weights;a<-a_sample$counts;b<-b_sample$counts;supported<-sum(a)>0&&sum(b)>0;findings<-structure(list(),names=character());pa<-if(sum(a)>0)a/sum(a)else NULL;pb<-if(sum(b)>0)b/sum(b)else NULL;psi_a<-psi_b<-NULL
 if(supported){smooth<-function(counts){scaling<-max(counts,alpha,1);v<-counts/scaling+alpha/scaling;v/sum(v)};psi_a<-smooth(a);psi_b<-smooth(b)
 if('psi'%in%metric_names){parts<-vector('list',size);infinite<-FALSE;for(i in seq_len(size)){p<-psi_a[i];q<-psi_b[i];if(p==q)parts[i]<-list(0)else if(p==0||q==0){parts[i]<-list(NULL);infinite<-TRUE}else parts[i]<-list((q-p)*(log(q)-log(p)))};findings$psi<-list(value=if(infinite)NULL else sum(unlist(parts)),status=if(infinite)'INFINITE'else'FINITE',contributions=parts,smoothing_pseudocount=alpha)}
 if('jsd'%in%metric_names){middle<-(pa+pb)/2;parts<-numeric(size);left<-pa>0;right<-pb>0;parts[left]<-parts[left]+.5*pa[left]*log(pa[left]/middle[left]);parts[right]<-parts[right]+.5*pb[right]*log(pb[right]/middle[right]);findings$jsd<-list(value=sum(parts),status='FINITE',contributions=as.list(parts),log_base='natural',smoothing_pseudocount=0)}
 if('wasserstein'%in%metric_names){ia<-!vapply(reference,missing,logical(1));ib<-!vapply(current,missing,logical(1));wa<-wr[ia];wb<-wc[ib];good<-sum(wa)>0&&sum(wb)>0;distance<-NULL;if(good){x<-as.numeric(unlist(reference[ia]));y<-as.numeric(unlist(current[ib]));grid<-sort(unique(c(x,y)));distance<-0;if(length(grid)>1L)for(i in seq_len(length(grid)-1L))distance<-distance+(grid[i+1L]-grid[i])*abs(sum(wa[x<=grid[i]])/sum(wa)-sum(wb[y<=grid[i]])/sum(wb))};if(!is.null(distance)&&!is.finite(distance)) .cr_error('VALIDATION_NUMERICAL','Wasserstein distance exceeds finite range');findings$wasserstein<-list(value=distance,status=if(good)'FINITE'else'NOT_APPLICABLE',reason=if(good)NULL else'NO_NONMISSING_SUPPORT',missing_policy='EXCLUDED_AND_REPORTED_SEPARATELY')}
 }else findings<-setNames(lapply(metric_names,function(name)list(value=NULL,status='NOT_APPLICABLE',reason='EMPTY_WEIGHTED_POPULATION')),metric_names)
 coverage<-list(reference_count=length(reference),current_count=length(current),reference_weight=sum(wr),current_weight=sum(wc),reference_missing_count=sum(vapply(reference,missing,logical(1))),current_missing_count=sum(vapply(current,missing,logical(1))),reference_missing_share=if(sum(wr)>0)sum(wr[vapply(reference,missing,logical(1))])/sum(wr)else NULL,current_missing_share=if(sum(wc)>0)sum(wc[vapply(current,missing,logical(1))])/sum(wc)else NULL,reference_novel_count=sum(vapply(reference,novel,logical(1))),current_novel_count=sum(vapply(current,novel,logical(1))),novel_definition=if(kind=='numeric')'OUTSIDE_DECLARED_REFERENCE_SUPPORT'else'UNSEEN_FIXED_CATEGORY');coverage['missing_share_change']<-list(if(is.null(coverage$reference_missing_share)||is.null(coverage$current_missing_share))NULL else coverage$current_missing_share-coverage$reference_missing_share)
 value<-list(artifact_type='ValidationResult',metrics=findings,uncertainty=list(status='NOT_REQUESTED',method=NULL),p_value=NULL,decision=list(status='NOT_ASSESSED',rule=NULL),applicability=if(supported)'APPLICABLE'else'NOT_APPLICABLE',reason=if(supported)NULL else'EMPTY_WEIGHTED_POPULATION',design=d,binning=spec,coverage=coverage,reference_counts=as.list(a),current_counts=as.list(b),reference_shares=if(is.null(pa))NULL else as.list(pa),current_shares=if(is.null(pb))NULL else as.list(pb),psi_reference_shares=if(is.null(psi_a))NULL else as.list(psi_a),psi_current_shares=if(is.null(psi_b))NULL else as.list(psi_b),input_fingerprint=.cr_hash(list(reference=lapply(reference,function(v)if(missing(v))NULL else v),current=lapply(current,function(v)if(missing(v))NULL else v),reference_weights=as.list(wr),current_weights=as.list(wc))));.cr_result(value,'validation.population_stability','distribution_distance',context,limitations='Distances are descriptive with no universal PSI threshold or statistical/concept-drift conclusion. PSI smooths fixed bin counts only; JSD uses empirical masses; Wasserstein uses observed raw numeric values.')
}
